<?php
/**
 * South theme setup.
 *
 * South is a block theme: the layout lives in templates/*.html, the design
 * system in theme.json (generated by .dev/build_theme.py) and the sections in
 * patterns/*.php (generated by .dev/build_patterns.py). This file carries only
 * what those cannot express: supports, assets, block styles, pattern
 * categories, and the modules in inc/.
 *
 * Homes, agents and the property search belong to the companion plugin, South
 * Listings. The theme works and looks complete without it: see inc/listings.php.
 *
 * @package South
 */

defined( 'ABSPATH' ) || exit;

define( 'SOUTH_VERSION', '1.0.0' );

/**
 * Theme supports.
 */
function south_setup() {
	load_theme_textdomain( 'south', get_template_directory() . '/languages' );

	add_theme_support( 'title-tag' );
	add_theme_support( 'post-thumbnails' );
	add_theme_support( 'automatic-feed-links' );
	add_theme_support( 'html5', array( 'search-form', 'comment-form', 'comment-list', 'gallery', 'caption', 'style', 'script' ) );
	add_theme_support( 'editor-styles' );
	add_theme_support( 'responsive-embeds' );
	add_theme_support( 'align-wide' );
	add_theme_support( 'wp-block-styles' );
	add_theme_support(
		'custom-logo',
		array(
			'height'      => 34,
			'width'       => 136,
			'flex-height' => true,
			'flex-width'  => true,
		)
	);

	// The same rules in the editor canvas as on the site.
	add_editor_style( array( 'style.css', 'assets/css/scheme.css' ) );
}
add_action( 'after_setup_theme', 'south_setup' );

/**
 * Front-end styles.
 */
function south_enqueue_styles() {
	wp_enqueue_style( 'south-style', get_stylesheet_uri(), array(), SOUTH_VERSION );
}
add_action( 'wp_enqueue_scripts', 'south_enqueue_styles' );

/**
 * The sliders, the sticky header, the map that loads on request and the
 * form's sending state.
 *
 * Deferred and in the footer: everything it does is an enhancement. With
 * JavaScript off the first slide shows, every slide's content is in the page,
 * the map card's "Open in maps" link works and forms submit normally.
 * Settings go in as JSON, not wp_localize_script(), which turns `false` into
 * an empty string.
 */
function south_enqueue_scripts() {
	wp_enqueue_script(
		'south-interactions',
		get_template_directory_uri() . '/assets/js/south.js',
		array(),
		SOUTH_VERSION,
		array(
			'in_footer' => true,
			'strategy'  => 'defer',
		)
	);

	wp_add_inline_script(
		'south-interactions',
		'window.southSettings = ' . wp_json_encode(
			array(
				/**
				 * Filters whether the hero slider advances by itself.
				 *
				 * @param bool $autoplay Default true; reduced-motion visitors never get it.
				 */
				'autoplay'  => (bool) apply_filters( 'south_hero_autoplay', true ),
				'previous'  => __( 'Previous', 'south' ),
				'next'      => __( 'Next', 'south' ),
				/* translators: %d: slide number. */
				'slide'     => __( 'Show slide %d', 'south' ),
				'mapTitle'  => __( 'Map', 'south' ),
				'mapLoaded' => __( 'Map loaded', 'south' ),
			)
		) . ';',
		'before'
	);
}
add_action( 'wp_enqueue_scripts', 'south_enqueue_scripts' );

/**
 * Block style variations.
 *
 * The CSS for each lives in style.css, never behind a `style_handle`: that
 * handle only loads while WordPress serves separate core block assets, which
 * any plugin can switch off (Academia's variations rendered unstyled that way).
 */
function south_register_block_styles() {
	$styles = array(
		'core/button' => array(
			array( 'south-outline', __( 'Outline', 'south' ) ),
			array( 'south-dark', __( 'Dark', 'south' ) ),
		),
		'core/group'  => array(
			array( 'south-panel', __( 'Grey panel', 'south' ) ),
		),
		'core/list'   => array(
			array( 'south-checks', __( 'Check list', 'south' ) ),
		),
	);

	foreach ( $styles as $block => $variations ) {
		foreach ( $variations as $variation ) {
			list( $name, $label ) = $variation;
			register_block_style(
				$block,
				array(
					'name'  => $name,
					'label' => $label,
				)
			);
		}
	}
}
add_action( 'init', 'south_register_block_styles' );

/**
 * Pattern categories, registered on init so the labels translate.
 */
function south_register_pattern_categories() {
	$categories = array(
		'south-sections' => array(
			'label'       => __( 'South: sections', 'south' ),
			'description' => __( 'Full-width sections for building pages.', 'south' ),
		),
		'south-listings' => array(
			'label'       => __( 'South: listings', 'south' ),
			'description' => __( 'Property search and listing grids. They need the South Listings plugin.', 'south' ),
		),
		'south-pages'    => array(
			'label'       => __( 'South: pages', 'south' ),
			'description' => __( 'Complete page layouts.', 'south' ),
		),
	);

	foreach ( $categories as $slug => $args ) {
		register_block_pattern_category( $slug, $args );
	}
}
add_action( 'init', 'south_register_pattern_categories' );

require get_template_directory() . '/inc/listings.php';
require get_template_directory() . '/inc/front-page-setup.php';
require get_template_directory() . '/inc/enquiry.php';
require get_template_directory() . '/inc/journal.php';
require get_template_directory() . '/inc/forms.php';
require get_template_directory() . '/inc/scheme.php';
require get_template_directory() . '/inc/updates.php';
